mapper.select:
select vo.ORDER_ID as orderId, /** 指令编号 **/ d.TRADE_ID as tradeId, /**交易编号**/ cp.FINPROD_ID as prodId, /**投资主体代码**/ cp.FINPROD_ABBR as prodAbbr, /**投资主体名称**/ zc.FINPROD_ID as assetId, /**资产代码**/ zc.FINPROD_ABBR as assetAbbr, /**资产简称**/ d.finprod_type as finprodTypeCode,/**拆借方向Code - 产品类型**/ d.finprod_type as finprodType,/**拆借方向 - 产品类型**/ vo.PS as psCode, /** 收付方向Code **/ vo.PS as ps, /** 收付方向 **/ DATE_FORMAT(vo.SETTLE_DATE, '%Y-%m-%d') as settleDate, /** 结算日期 **/ vo.MY_ACCT_NO as myAcctNo, /** 本方资金账户 **/ vo.COUNTER_ACCT_NO as counterAcctNo, /** 对手方资金账户 **/ voi1.ACCT_NAME as myAcctName, /**出/收款账户 - 本方资金账户**/ voi2.ACCT_NAME as counterAcctName,/**对手方资金账户 **/ vo.CCY as ccyCode, /** 币种Code **/ vo.CCY as ccy, /** 币种 **/ vo.ORDER_TYPE as orderTypeCode, /** 指令类型Code **/ vo.ORDER_TYPE as orderType, /** 指令类型 **/ d.IS_CLEAN as isClean, /** 是否结清 **/ IFNULL(tdf.FEE_AMT,'0') as tdFeeAmt, /**通道费**/ vo.SETTLE_AMT as settleAmt, /** 结算金额 **/ vo.SETTLE_STATUS as settleStatusCode, /** 结算状态Code **/ vo.SETTLE_STATUS as settleStatus /** 结算状态 **/ from trd_PRODUCT_DEAL d left join FIN_PRODUCT zc on zc.finprod_id = d.finprod_id
left join TRD_PRODUCT_DEAL_ADD e on d.trade_id = e.trade_id
/**【一体化注释：金融产品交易附属表TRD_PRODUCT_DEAL_ADD去除对PROD_ID字段】**/ /**left join FIN_PRODUCT cp on cp.finprod_id = e.prod_id**/ left join FIN_PRODUCT cp on cp.finprod_id = '不进行关联'
inner join stl_ORDERS vo on vo.trade_id = d.trade_id /*关联结算指令表时，一定要关联结算指令扩展表，加上关联条件是否随交易出账='N'的条件 2018-12-17 王耕耘与褚密分析结果*/ inner join Stl_Orders_Ext stl_ext on vo.order_id=stl_ext.order_id and stl_ext.is_trade='N' left join TRD_TRADE_FEE_DETAIL tdf on tdf.trade_id = d.trade_id and tdf.fee_type = 'B09' left join STL_CAPACCT_INFO voi1 on voi1.acct_no = vo.my_acct_no left join STL_CAPACCT_INFO voi2 on voi2.acct_no = vo.counter_acct_no where vo.order_id = #{orderId}

select vo.ORDER_ID as orderId, /** 指令编号 **/ d.TRADE_ID as tradeId, /**交易编号**/ cp.FINPROD_ID as prodId, /**投资主体代码**/ cp.FINPROD_ABBR as prodAbbr, /**投资主体名称**/ zc.FINPROD_ID as assetId, /**资产代码**/ zc.finprod_abbr as assetAbbr, /**资产简称**/ d.finprod_type as finprodTypeCode,/**拆借方向Code - 产品类型**/ d.finprod_type as finprodType,/**拆借方向 - 产品类型**/ vo.PS as psCode, /** 收付方向Code **/ vo.PS as ps, /** 收付方向 **/ DATE_FORMAT(vo.SETTLE_DATE, '%Y-%m-%d') as settleDate, /** 结算日期 **/ vo.MY_ACCT_NO as myAcctNo, /** 本方资金账户 **/ vo.COUNTER_ACCT_NO as counterAcctNo, /** 对手方资金账户 **/ voi1.ACCT_NAME as myAcctName, /**出/收款账户 - 本方资金账户**/ voi2.ACCT_NAME as counterAcctName,/**对手方资金账户 **/ vo.CCY as ccyCode, /** 币种Code **/ vo.CCY as ccy, /** 币种 **/ vo.ORDER_TYPE as orderTypeCode, /** 指令类型Code **/ vo.ORDER_TYPE as orderType, /** 指令类型 **/ d.IS_CLEAN as isClean, /** 是否结清 **/ IFNULL(tdf.FEE_AMT,'0') as tdFeeAmt, /**通道费**/ vo.SETTLE_AMT as settleAmt, /** 结算金额 **/ vo.SETTLE_STATUS as settleStatusCode, /** 结算状态Code **/ vo.SETTLE_STATUS as settleStatus /** 结算状态 **/ from trd_PRODUCT_DEAL d left join FIN_PRODUCT zc on zc.finprod_id = d.finprod_id and zc.finprod_type = d.finprod_type
left join TRD_PRODUCT_DEAL_ADD e on d.trade_id = e.trade_id
/**【一体化注释：金融产品交易附属表TRD_PRODUCT_DEAL_ADD去除对PROD_ID字段】**/ /**left join FIN_PRODUCT cp on cp.finprod_id = e.prod_id**/ left join FIN_PRODUCT cp on cp.finprod_id = '不进行关联'
inner join stl_ORDERS vo on vo.trade_id = d.trade_id /*关联结算指令表时，一定要关联结算指令扩展表，加上关联条件是否随交易出账='N'的条件 2018-12-17 王耕耘与褚密分析结果*/ inner join Stl_Orders_Ext stl_ext on vo.order_id=stl_ext.order_id and stl_ext.is_trade='N' left join TRD_TRADE_FEE_DETAIL tdf on tdf.trade_id = d.trade_id and tdf.fee_type = 'B09' left join STL_CAPACCT_INFO voi1 on voi1.acct_no = vo.my_acct_no left join STL_CAPACCT_INFO voi2 on voi2.acct_no = vo.counter_acct_no where vo.order_id = #{orderId}
